import{_ as o,C as l,o as d,c as n,a2 as e,b as i,w as a,a as s,E as h,a3 as c}from"./chunks/framework.CAKCj7G0.js";const C=JSON.parse('{"title":"Set 接口","description":"","frontmatter":{},"headers":[],"relativePath":"Java/Java/集合/Collection/Set/Set.md","filePath":"Java/Java/集合/Collection/Set/Set.md","lastUpdated":1762838572000}'),S={name:"Java/Java/集合/Collection/Set/Set.md"};function b(u,t,p,_,m,A){const r=l("Mermaid");return d(),n("div",null,[t[1]||(t[1]=e('<h1 id="set-接口" tabindex="-1">Set 接口 <a class="header-anchor" href="#set-接口" aria-label="Permalink to &quot;Set 接口&quot;">​</a></h1><h2 id="一、概念与定位" tabindex="-1">一、概念与定位 <a class="header-anchor" href="#一、概念与定位" aria-label="Permalink to &quot;一、概念与定位&quot;">​</a></h2><p>Set 接口是 Java 集合框架中的重要接口，继承自 Collection 接口，代表一个<strong>不包含重复元素</strong>的集合。Set 接口的核心特性是<strong>无序性</strong>和<strong>不可重复性</strong>（具体实现类可能有所不同，如 TreeSet 是有序的）。</p><h3 id="核心特性" tabindex="-1">核心特性 <a class="header-anchor" href="#核心特性" aria-label="Permalink to &quot;核心特性&quot;">​</a></h3><ul><li><strong>不可重复性</strong>：Set 中的元素不允许重复，这是其最基本的约束</li><li><strong>无序性</strong>：元素在 Set 中的存储位置通常不保证顺序（除有序实现外）</li><li><strong>单值存储</strong>：类似于数学中的集合概念，每个元素只能出现一次</li><li><strong>null 元素支持</strong>：大多数 Set 实现允许最多一个 null 元素</li></ul><h2 id="二、继承体系" tabindex="-1">二、继承体系 <a class="header-anchor" href="#二、继承体系" aria-label="Permalink to &quot;二、继承体系&quot;">​</a></h2><p>Set 接口继承自 Collection 接口，主要实现类包括：</p>',7)),(d(),i(c,null,{default:a(()=>[h(r,{id:"mermaid-40",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20Collection%20--%3E%20Set%0A%20%20%20%20Set%20--%3E%20HashSet%0A%20%20%20%20Set%20--%3E%20AbstractSet%0A%20%20%20%20HashSet%20--%3E%20LinkedHashSet%0A%20%20%20%20AbstractSet%20--%3E%20TreeSet%0A%20%20%20%20AbstractSet%20--%3E%20EnumSet%0A%20%20%20%20AbstractSet%20--%3E%20ConcurrentSkipListSet%0A%20%20%20%20Set%20--%3E%20CopyOnWriteArraySet%0A"})]),fallback:a(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=e('<h2 id="三、实现类比较" tabindex="-1">三、实现类比较 <a class="header-anchor" href="#三、实现类比较" aria-label="Permalink to &quot;三、实现类比较&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>HashSet</th><th>LinkedHashSet</th><th>TreeSet</th><th>EnumSet</th><th>CopyOnWriteArraySet</th><th>ConcurrentSkipListSet</th></tr></thead><tbody><tr><td>底层实现</td><td>HashMap（哈希表）</td><td>LinkedHashMap（链表+哈希表）</td><td>TreeMap（红黑树）</td><td>位向量</td><td>CopyOnWriteArrayList（数组）</td><td>跳表</td></tr><tr><td>元素顺序</td><td>无序（哈希顺序）</td><td>插入顺序</td><td>自然顺序或指定比较器</td><td>枚举声明顺序</td><td>插入顺序</td><td>自然顺序或指定比较器</td></tr><tr><td>时间复杂度</td><td>添加/删除/查询 O(1)（平均）</td><td>添加/删除/查询 O(1)（平均）</td><td>添加/删除/查询 O(log n)</td><td>添加/删除/查询 O(1)</td><td>添加 O(n)，查询 O(1)</td><td>添加/删除/查询 O(log n)</td></tr><tr><td>null 值支持</td><td>允许一个 null</td><td>允许一个 null</td><td>JDK 7+ 不允许</td><td>不允许</td><td>允许一个 null</td><td>不允许</td></tr><tr><td>线程安全</td><td>否</td><td>否</td><td>否</td><td>否</td><td>是</td><td>是</td></tr><tr><td>内存开销</td><td>中</td><td>高（额外链表结构）</td><td>高（红黑树结构）</td><td>低（位向量）</td><td>高（写时复制）</td><td>高（跳表结构）</td></tr><tr><td>适用场景</td><td>快速查找，不关心顺序</td><td>需要保持插入顺序的快速查找</td><td>需要排序或范围查询</td><td>枚举类型集合</td><td>读多写少的并发场景</td><td>高并发下的有序集合</td></tr></tbody></table><h2 id="四、set-接口的常用方法" tabindex="-1">四、Set 接口的常用方法 <a class="header-anchor" href="#四、set-接口的常用方法" aria-label="Permalink to &quot;四、Set 接口的常用方法&quot;">​</a></h2><p>Set 接口继承了 Collection 接口的所有方法，并添加了一些特有方法（主要是对重复元素的处理）：</p><table tabindex="0"><thead><tr><th>方法</th><th>描述</th></tr></thead><tbody><tr><td>boolean add(E e)</td><td>如果集合中不存在指定元素，则添加该元素，返回 true</td></tr><tr><td>boolean addAll(Collection&lt;? extends E&gt; c)</td><td>将指定集合中的所有元素添加到此集合中（不包含重复元素）</td></tr><tr><td>void clear()</td><td>移除集合中的所有元素</td></tr><tr><td>boolean contains(Object o)</td><td>如果集合包含指定元素，则返回 true</td></tr><tr><td>boolean containsAll(Collection&lt;?&gt; c)</td><td>如果集合包含指定集合的所有元素，则返回 true</td></tr><tr><td>boolean isEmpty()</td><td>如果集合不包含元素，则返回 true</td></tr><tr><td>Iterator&lt;E&gt; iterator()</td><td>返回此集合中元素的迭代器</td></tr><tr><td>boolean remove(Object o)</td><td>如果存在指定元素，则从集合中移除该元素</td></tr><tr><td>boolean removeAll(Collection&lt;?&gt; c)</td><td>移除集合中包含在指定集合中的所有元素</td></tr><tr><td>boolean retainAll(Collection&lt;?&gt; c)</td><td>仅保留集合中包含在指定集合中的元素</td></tr><tr><td>int size()</td><td>返回集合中的元素数量</td></tr><tr><td>Object[] toArray()</td><td>返回包含集合中所有元素的数组</td></tr><tr><td>&lt;T&gt; T[] toArray(T[] a)</td><td>返回包含集合中所有元素的指定类型数组</td></tr></tbody></table>',5))])}const T=o(S,[["render",b]]);export{C as __pageData,T as default};
